"""Lazy, original CARLA pedestrian and four-camera frame acquisition checks.

The caller owns CARLA world setup, media encoding, and attempt sealing. These
checks run before an acquired frame is accepted as source evidence.
"""
from __future__ import annotations

import math
import queue
import subprocess
from pathlib import Path

from corridor_construction import validate_scene


CAMERA_SPECS = {"overview": (1920, 1080), "approach": (1280, 720),
                "reference_corner": (1280, 720),
                "driver_reference": (1280, 720)}


def camera_placements(scene):
    """Aim context cameras toward the middle of the exact walking route."""
    validate_scene(scene)
    x = scene["pedestrian_route_xy_m"][1][0]
    y = scene["pedestrian_route_xy_m"][1][1]
    sidewalk = scene["bounds_xy_m"]["sidewalk"]
    trail = scene["bounds_xy_m"]["nonmotorized_trail"]
    sites = {"overview": (x, 14.0, 25.0),
             "approach": (x-8.0, y-6.0, 4.0),
             "reference_corner": (x+4.0, sidewalk[3]+2.0, 5.0),
             "driver_reference": (x-4.0, trail[3]+2.0, 5.0)}
    target = (x, y, 1.0)
    placements = {}
    for name, location in sites.items():
        dx, dy, dz = (target[i]-location[i] for i in range(3))
        yaw = math.degrees(math.atan2(dy, dx))
        pitch = math.degrees(math.atan2(dz, math.hypot(dx, dy)))
        placements[name] = {"location_xyz_m": location,
                            "rotation_pitch_yaw_deg": (pitch, yaw),
                            "target_xyz_m": target}
    return placements


def spawn_native_cameras(world, scene, carla):
    """Construct four RGB sensors; destroy partial spawns on any failure."""
    placements = camera_placements(scene)
    sensors = {}
    try:
        for name, (width, height) in CAMERA_SPECS.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            if blueprint is None:
                raise ValueError("Native RGB camera blueprint missing")
            for key, value in (("image_size_x", width), ("image_size_y", height),
                               ("fov", 75)):
                blueprint.set_attribute(key, str(value))
            placement = placements[name]
            x, y, z = placement["location_xyz_m"]
            pitch, yaw = placement["rotation_pitch_yaw_deg"]
            transform = carla.Transform(carla.Location(x=x, y=y, z=z),
                                        carla.Rotation(pitch=pitch, yaw=yaw))
            sensor = world.spawn_actor(blueprint, transform)
            if sensor is None:
                raise ValueError(name+" Native camera spawn failed")
            sensors[name] = sensor
        return sensors
    except BaseException:
        for sensor in reversed(list(sensors.values())):
            sensor.destroy()
        raise


def sample_original_walker(scene, actor, snapshot):
    """Read the actor's world-space bounding box, not its commanded route."""
    frame = int(snapshot.frame)
    time_s = float(snapshot.timestamp.elapsed_seconds)
    if frame < 0 or not math.isfinite(time_s):
        raise ValueError("invalid original world frame or timestamp")
    transform = actor.get_transform()
    vertices = actor.bounding_box.get_world_vertices(transform)
    if len(vertices) != 8:
        raise ValueError("original walker needs eight world-space body vertices")
    xyz = [(float(v.x), float(v.y), float(v.z)) for v in vertices]
    if not all(math.isfinite(v) for point in xyz for v in point):
        raise ValueError("nonfinite original walker body")
    xs = [point[0] for point in xyz]
    ys = [point[1] for point in xyz]
    if max(xs)-min(xs) < .1 or max(ys)-min(ys) < .1:
        raise ValueError("degenerate original walker footprint")
    body = [[min(xs), min(ys)], [max(xs), min(ys)],
            [max(xs), max(ys)], [min(xs), max(ys)]]
    return {"case_id": scene["case_id"], "actor_id": int(actor.id),
            "frame": frame, "time_s": time_s, "body_xy_m": body,
            "body_z_min_m": min(point[2] for point in xyz),
            "body_z_max_m": max(point[2] for point in xyz),
            "source_kind": "original_native_world_vertices"}


class FourViewJoin:
    """Reject incomplete, stale or malformed camera frames before encoding."""

    def __init__(self):
        self.previous_frame = None
        self.previous_time_s = None

    def append(self, walker_sample, images):
        frame = walker_sample["frame"]
        time_s = walker_sample["time_s"]
        if self.previous_frame is not None:
            if frame != self.previous_frame+1:
                raise ValueError("original world frames are not consecutive")
            if abs(time_s-self.previous_time_s-.05) > .005:
                raise ValueError("original world frame timing is not 20 Hz")
        if set(images) != set(CAMERA_SPECS):
            raise ValueError("four named original camera views required")
        receipt = {"case_id": walker_sample["case_id"], "frame": frame,
                   "time_s": time_s, "walker_actor_id": walker_sample["actor_id"],
                   "cameras": {}}
        for name, (width, height) in CAMERA_SPECS.items():
            image = images[name]
            if (int(image.frame) != frame or int(image.width) != width or
                    int(image.height) != height or len(image.raw_data) != width*height*4):
                raise ValueError(name+" original camera frame, resolution or BGRA size differs")
            receipt["cameras"][name] = {"frame": frame, "width": width,
                                        "height": height, "pixel_format": "bgra",
                                        "bytes": width*height*4}
        self.previous_frame = frame
        self.previous_time_s = time_s
        return receipt


class FourVideoRecorder:
    """Acquire four synchronized original BGRA streams into lossless videos.

    A failed frame leaves the attempt incomplete. The caller must seal only after
    `close` succeeds and an independent decoder checks every resulting video.
    """

    def __init__(self, world, scene, carla, output, encoder_factory=None):
        self.output = Path(output)
        if not self.output.is_dir():
            raise ValueError("fresh existing Native attempt directory required")
        if any((self.output/(name+".mkv")).exists() for name in CAMERA_SPECS):
            raise ValueError("Native video outputs already exist")
        self.join = FourViewJoin()
        self.queues = {}
        self.sensors = {}
        self.encoders = {}
        self.errors = []
        self.closed = False
        encoder_factory = encoder_factory or subprocess.Popen
        try:
            self.sensors = spawn_native_cameras(world, scene, carla)
            for name, (width, height) in CAMERA_SPECS.items():
                inbox = queue.Queue(maxsize=4)
                self.queues[name] = inbox

                def receive(image, target=inbox, label=name):
                    try:
                        target.put_nowait(image)
                    except queue.Full:
                        self.errors.append("camera queue overflow: "+label)

                self.sensors[name].listen(receive)
                command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                           "-n", "-f", "rawvideo", "-pixel_format", "bgra",
                           "-video_size", f"{width}x{height}", "-framerate", "20",
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-pix_fmt", "bgra",
                           str(self.output/(name+".mkv"))]
                self.encoders[name] = encoder_factory(
                    command, stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def append(self, walker_sample):
        if self.closed:
            raise ValueError("Native video recorder already closed")
        if self.errors:
            raise RuntimeError("; ".join(self.errors))
        images = {name: self.queues[name].get(timeout=15) for name in CAMERA_SPECS}
        receipt = self.join.append(walker_sample, images)
        for name, image in images.items():
            written = self.encoders[name].stdin.write(image.raw_data)
            if written != len(image.raw_data):
                raise RuntimeError(name+" encoder wrote incomplete original frame")
        return receipt

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.stop()
            except BaseException as exc: errors.append("sensor stop: "+repr(exc))
        for name, encoder in self.encoders.items():
            try:
                if encoder.stdin and not encoder.stdin.closed:
                    encoder.stdin.close()
                if encoder.wait(timeout=180) != 0:
                    errors.append(name+" encoder failed")
            except BaseException as exc:
                errors.append(name+" encoder close: "+repr(exc))
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.destroy()
            except BaseException as exc: errors.append("sensor destroy: "+repr(exc))
        if errors:
            raise RuntimeError("; ".join(errors))

"""Portable engineering corridor for the selected sidewalk and trail branch.

Coordinates are an authored CPU candidate, not a reviewed municipal map.
"""
from __future__ import annotations

import math

from corridor_map import BANDS, map_sha256
ROUTES = {"roadway": 1.5, "shoulder": 3.5, "sidewalk": 5.0}


def make_scene(case_id, route_band):
    if route_band not in ROUTES:
        raise ValueError("unknown pedestrian route band")
    y = ROUTES[route_band]
    scene = {
        "case_id": case_id,
        "map_kind": "authored_cpu_candidate",
        "map_source_sha256": map_sha256(),
        "bounds_xy_m": {name: [0.0, low, 30.0, high] for name, (low, high) in BANDS.items()},
        "sidewalk_provided_claim": "authored_geometry_only",
        "sidewalk_adjacent_to_roadway": True,
        "trail_access_status": "unreviewed_nonmotorized_context",
        "pedestrian_route_xy_m": [[2.0, y], [15.0, y], [28.0, y]],
        "pedestrian_body_half_width_m": 0.25,
        "route_band": route_band,
        "legal_judgment": "unresolved",
        "physical_acceptance_claimed": False,
    }
    validate_scene(scene)
    return scene


def validate_scene(scene):
    if scene.get("map_source_sha256") != map_sha256():
        raise ValueError("authored corridor map source hash differs")
    bounds = scene["bounds_xy_m"]
    if set(bounds) != set(BANDS):
        raise ValueError("roadway, shoulder, sidewalk, buffer and trail required")
    bands = sorted((rect[1], rect[3], name) for name, rect in bounds.items())
    if any(low >= high for low, high, _ in bands):
        raise ValueError("empty corridor band")
    for (_, high, _), (low, _, _) in zip(bands, bands[1:]):
        if abs(high-low) > 1e-9:
            raise ValueError("corridor bands have an overlap or gap")
    if [name for _, _, name in bands] != ["roadway", "shoulder", "sidewalk", "buffer", "nonmotorized_trail"]:
        raise ValueError("sidewalk is not adjacent to shoulder and roadway")
    route = scene["pedestrian_route_xy_m"]
    half = scene["pedestrian_body_half_width_m"]
    if len(route) < 3 or not 0 < half < .5:
        raise ValueError("invalid pedestrian route or body width")
    if any(not all(math.isfinite(v) for v in point) for point in route):
        raise ValueError("nonfinite route point")
    if any(b[0] <= a[0] for a, b in zip(route, route[1:])):
        raise ValueError("pedestrian route does not walk along corridor")
    target = bounds[scene["route_band"]]
    if any(not (target[0] <= x <= target[2] and target[1] <= y-half and y+half <= target[3])
           for x, y in route):
        raise ValueError("pedestrian body leaves its authored route band")
    if scene["legal_judgment"] != "unresolved" or scene["physical_acceptance_claimed"]:
        raise ValueError("engineering candidate cannot claim legal or physical acceptance")
    return True


def request_next_target(scene, x, y, target_index=1):
    """Return a walker target request; original movement is audited separately."""
    validate_scene(scene)
    route = scene["pedestrian_route_xy_m"]
    if not 1 <= target_index < len(route):
        raise ValueError("invalid target index")
    if math.hypot(x-route[target_index][0], y-route[target_index][1]) < .5 and target_index < len(route)-1:
        target_index += 1
    tx, ty = route[target_index]
    distance = math.hypot(tx-x, ty-y)
    return {"target_index": target_index, "target_xy_m": [tx, ty],
            "direction_xy": [0.0, 0.0] if distance == 0 else [(tx-x)/distance, (ty-y)/distance],
            "speed_mps": 0.0 if distance < .5 and target_index == len(route)-1 else 1.2}


def measure_original(scene, frames):
    """Classify original full-body footprints, without deciding legal sufficiency."""
    validate_scene(scene)
    if len(frames) < 3 or [f["frame"] for f in frames] != list(range(frames[0]["frame"], frames[0]["frame"]+len(frames))):
        raise ValueError("missing or stale original frames")
    counts = {name: 0 for name in BANDS}
    centers = []
    times = []
    for f in frames:
        time_s = float(f["time_s"])
        if not math.isfinite(time_s):
            raise ValueError("nonfinite original frame time")
        times.append(time_s)
        body = f["body_xy_m"]
        if len(body) != 4 or any(len(point) != 2 for point in body):
            raise ValueError("original full-body polygon required")
        if not all(math.isfinite(v) for point in body for v in point):
            raise ValueError("nonfinite original body")
        xs = [p[0] for p in body]
        ys = [p[1] for p in body]
        centers.append((sum(xs)/4, sum(ys)/4))
        covered = False
        for name, (low, high) in BANDS.items():
            if max(xs) >= 0 and min(xs) <= 30 and max(ys) >= low and min(ys) <= high:
                counts[name] += 1
                covered = True
        if not covered:
            raise ValueError("original pedestrian body is outside corridor")
    if centers[-1][0]-centers[0][0] < .1:
        raise ValueError("original pedestrian did not progress along corridor")
    if any(b[0] < a[0]-.05 for a, b in zip(centers, centers[1:])):
        raise ValueError("original pedestrian reversed along corridor")
    if any(abs((b-a)-.05) > .005 for a, b in zip(times, times[1:])):
        raise ValueError("original frame timing is not 20 Hz")
    speeds = [(b[0]-a[0])/(tb-ta) for a, b, ta, tb in
              zip(centers, centers[1:], times, times[1:])]
    if any(abs(speed) > 2.0 for speed in speeds):
        raise ValueError("original pedestrian motion exceeds engineering speed envelope")
    endpoint = scene["pedestrian_route_xy_m"][-1]
    reached_endpoint = math.hypot(centers[-1][0]-endpoint[0],
                                  centers[-1][1]-endpoint[1]) <= .5
    band = scene["bounds_xy_m"][scene["route_band"]]
    all_body_inside_route_band = all(
        min(p[0] for p in f["body_xy_m"]) >= band[0] and
        max(p[0] for p in f["body_xy_m"]) <= band[2] and
        min(p[1] for p in f["body_xy_m"]) >= band[1] and
        max(p[1] for p in f["body_xy_m"]) <= band[3]
        for f in frames)
    return {"frames": len(frames), "band_overlap_frame_counts": counts,
            "first_center_xy_m": list(centers[0]), "last_center_xy_m": list(centers[-1]),
            "duration_s": times[-1]-times[0], "maximum_forward_speed_mps": max(speeds),
            "authored_endpoint_reached": reached_endpoint,
            "all_body_inside_route_band": all_body_inside_route_band,
            "legal_judgment": "unresolved", "physical_acceptance_claimed": False}


def compare_authored_routes(first, second, declared_band_change):
    """Isolate the lateral route request in two engineering scenes."""
    validate_scene(first)
    validate_scene(second)
    if first["bounds_xy_m"] != second["bounds_xy_m"]:
        raise ValueError("corridor geometry changed")
    if first["map_source_sha256"] != second["map_source_sha256"]:
        raise ValueError("corridor map source changed")
    for key in ("sidewalk_provided_claim", "sidewalk_adjacent_to_roadway",
                "trail_access_status", "pedestrian_body_half_width_m"):
        if first[key] != second[key]:
            raise ValueError("fixed corridor context changed")
    if not declared_band_change or first["route_band"] == second["route_band"]:
        raise ValueError("lateral route change was not declared and realized")
    xs1 = [point[0] for point in first["pedestrian_route_xy_m"]]
    xs2 = [point[0] for point in second["pedestrian_route_xy_m"]]
    if xs1 != xs2:
        raise ValueError("longitudinal route changed")
    return {"fixed_corridor_and_longitudinal_route": True,
            "changed_route_bands": [first["route_band"], second["route_band"]],
            "realized_movement_claimed": False, "legal_judgment": "unresolved"}

